G=load()
def f(gin):
    A=np.array(gin)
    bests=[]
    for c in set(A.flatten())-{0}:
        ys,xs=np.where(A==c)
        y0,y1,x0,x1=ys.min(),ys.max(),xs.min(),xs.max()
        sub=A[y0:y1+1,x0:x1+1]
        n=int(sub==c).sum()
        bests.append((y0,x0,int(sub.shape[0]),int(sub.shape[1]),c,n))
    t=max(bests,key=lambda b:b[5])
    y0,x0,h,w,tc,_=t
    tp=A[y0:y0+h,x0:x0+w]
    out=np.zeros_like(A)
    for y0_,x0_,h2,w2,c2,n2 in bests:
        if (y0_,x0_)==(y0,x0) or (h2,w2)!=(h,w):
            continue
        out[y0_:y0_+h, x0_:x0_+w]=np.where(tp==tc,c2,0)
    return out.tolist()
