import numpy as np, os, re
from scipy import ndimage
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def show(m):
    for r in m: print(''.join(str(x) if x else '.' for x in r))

def frames(g):
    A=np.array(g); out=[]
    for c in sorted(set(map(int,A.flatten()))-{0}):
        lab,n=ndimage.label(A==c)
        for i in range(1,n+1):
            yy,xx=np.where(lab==i)
            y0,y1,x0,x1=int(yy.min()),int(yy.max()),int(xx.min()),int(xx.max())
            s=A[y0:y1+1,x0:x1+1]
            if (s!=c).sum() > s.size*0.9: continue
            out.append((y0,x0,int(s.shape[0]),int(s.shape[1]),s.copy().tolist()))
    return out

def has_gap(f):
    sub=np.array(f[4])
    h,w=sub.shape
    interior=sub[1:h-1,1:w-1]
    return (interior!=sub).any()  # cells inside frame differing from color (zeros)

def solve(g):
    A=np.array(g); out=A.copy()
    fs=frames(g)
    tps=[f_ for f_ in fs if has_gap(f_)]
    assert len(tps)==1,(tps,)
    T=np.array(tps[0][4]); th,tw=T.shape
    for f in fs:
        y0,x0=f[0],f[1]
        fh,fw=len(f[4]),len(f[4][0])
        if f is tps[0]: continue
        if (fh,fw)!=(th,tw):
            out[y0:y0+fh,x0:x0+fw]=0; continue
        c=int(np.unique(np.array(f[4]))[0])
        out[y0:y0+fh,x0:x0+fw]=np.where((T!=0),c,out[y0:y0+fh,x0:x0+fw])
    return out.tolist()

for dn in [1,2,3]:
    go=np.array(G[f'Demo pair {dn} output']); g2=np.array(solve(G[f'Demo pair {dn} input']))
    print(dn,(g2==go).all(),(g2!=go).sum())

